(#{version.id}, #{id}, #{version.version}, #{version.path}, #{version.fileSize}, #{version.fileMd5}, #{version.createTime}, #{version.changelog}, #{version.entityPackage}, #{version.methodPackage}, #{version.compatibleVersion});


    INSERT INTO entity_info (id, plugin_version_id, name, entity_name, attributes) VALUES

        (#{entity.id}, #{version.id}, #{entity.name}, #{entity.entityName}, #{entity.attributes})
    ;



