        (#{methodClass.id}, #{version.id}, #{methodClass.className}, #{methodClass.simpleClassName}, #{methodClass.packageName})
    ;




            INSERT INTO method_info (id, method_class_id, name, return_type) VALUES

                (#{method.id}, #{methodClass.id}, #{method.name}, #{method.returnType})
            ;




