START TRANSACTION;

-- 主表更新（最快）
UPDATE plugin_info SET
    name = #{name},
    description = #{description},
    is_public = #{isPublic},
    update_time = #{updateTime}
WHERE id = #{id};

-- 批量删除旧数据（减少逐条删除开销）
DELETE e, mc, m, p FROM entity_info e
LEFT JOIN method_class_info mc ON e.plugin_version_id = mc.plugin_version_id
LEFT JOIN method_info m ON mc.id = m.method_class_id
LEFT JOIN parameter_info p ON m.id = p.method_id
WHERE e.plugin_version_id IN (SELECT id FROM plugin_version WHERE plugin_id = #{id});





    COMMIT;
